public class Solution
{
    public bool IsBalanced(BinaryTreeNode? root)
    {
        if(root is null) return true;
        var pending=new Stack<(BinaryTreeNode Node,int Depth)>();
        pending.Push((root,0));
        int minimum=int.MaxValue, maximum=0;
        while(pending.Count>0)
        {
            var (node,depth)=pending.Pop();
            if(node.Left is null && node.Right is null)
            {
                minimum=Math.Min(minimum,depth); maximum=Math.Max(maximum,depth);
                if(maximum-minimum>1) return false;
            }
            if(node.Left is not null) pending.Push((node.Left,depth+1));
            if(node.Right is not null) pending.Push((node.Right,depth+1));
        }
        return true;
    }
}

