    public long MaxDuffelBagValue(CakeType[] types,int capacity)
    {
        foreach(var type in types) if(type.Weight==0 && type.Value>0) throw new InfinityException();
        var best=new long[capacity+1];
        for(int weight=1;weight<=capacity;weight++)
            foreach(var type in types)
                if(type.Weight>0 && type.Weight<=weight) best[weight]=Math.Max(best[weight],best[weight-type.Weight]+type.Value);
        return best[capacity];
    }
}

