public class WordCloudData
{
    public IDictionary<string,int> WordsToCounts { get; }=new Dictionary<string,int>();
    private static bool Letter(char c) => c is >= 'a' and <= 'z' or >= 'A' and <= 'Z';
    public WordCloudData(string input)
    {
        int start=0;
        while(start<input.Length)
        {
            if(!Letter(input[start])) { start++; continue; }
            int end=start+1;
            while(end<input.Length)
            {
                if(Letter(input[end])) { end++; continue; }
                if(input[end] is '\'' or '-' && end+1<input.Length && Letter(input[end-1]) && Letter(input[end+1])) { end++; continue; }
                break;
            }
            string key=input[start..end].ToLowerInvariant();
            WordsToCounts.TryGetValue(key,out int count); WordsToCounts[key]=count+1; start=end;
        }
    }
}

